    local id2Res          = self.selectId2Res
    local isSelect        = not id2Res[id]

    ----------------------------------------
    --- 处理选择后的数据
    local res = self:HandleSelectData(goodsNodeData, id, isSelect)
    
    ----------------------------------------
    --- 处理选择后的UI
    if res then
        ---@type UICultivateEquipBackpackNodeMB
        local mbEnv = self:GetEquipmentListEnv()
        if mbEnv == nil then return end
        mbEnv:RefreshCellShowStateByIndex(index, isSelect)
        --self:FreshCellShowStateByIndex(index, isSelect)
        self:FreshChooseEquip()
    else
        GameUtils.Toast(localize("已达到单次回收数量上限"))
        return false
    end
    return true
end

