function CardProgressionEquipmentReclaimDialog:RefreshRewards()
    local isSelect       = self.selectCount > 0
    if not isSelect then
        CfUtils.SetActive(self.CanGet, false)
        return 
    end

    CfUtils.SetActive(self.CanGet, true)
    
    -- local normal = {}
    local normal = self.goodsId2Num
    local extra  = {}
    for id, v in pairs(self.selectId2Res) do
        if v then
            local equipDojo = equipComp:GetEquipById(id)
            local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
            local cnrVo = EquipUtils.GetEquipmentCNRVo({quality = equipVo.rare, star = equipDojo.star, level = equipDojo.level})
            -- if normal[cnrVo.recycleItem[3]] then
            --     normal[cnrVo.recycleItem[3]] = normal[cnrVo.recycleItem[3]] + checkInt(cnrVo.recycleItemNum[3])
            -- else
            --     normal[cnrVo.recycleItem[3]] = checkInt(cnrVo.recycleItemNum[3])
            -- end
            for _, v in ipairs(cnrVo.SuperSuccessExtraItem) do
                if not extra[v] then
                    extra[v] = true
                end
            end
            for _, v in ipairs(cnrVo.BigSuccessExtraItem) do
                if not extra[v] then
                    extra[v] = true
                end
            end
        end
    end
    local keys = sortByKey(normal, false)
    local normalData = {}
    for _, id in ipairs(keys) do
        local tmp = {
            goodsId = id,
            num = normal[id]
        }
        table.insert(normalData, tmp)
    end
    CfUtils.RefreshCommonGoodsList(self.CommonGoodsList, normalData)
    
    local exKeys = sortByKey(extra, false)
    for _, v in ipairs(self.goodsGroup) do
        CfUtils.SetActive(v, false)
    end
    
    CfUtils.SetActive(self.Probability, next(exKeys) ~= nil and true or false)
    for i, id in ipairs(exKeys) do
        if not self.goodsGroup[i] then
            if i == 1 then
                table.insert(self.goodsGroup, self.GoodNode)
            else
                local node = self.Gridlayout.gameObject:AddChild(self.GoodNode.gameObject)
                table.insert(self.goodsGroup, node)
            end
        end
        local node = self.goodsGroup[i]
        CfUtils.SetActive(node, true)
        CfUtils.RefeshGoodGo2(node, id, nil, nil, nil, function()
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
            GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
        end)
    end
end

