--- HandleSelectData
--- 处理选择数据
---@param goodsNodeData table
---@param id number
---@param isSelect boolean
function CardProgressionEquipmentReclaimDialog:HandleSelectData(goodsNodeData, id, isSelect, isFastSelect)
    local id2Res          = self.selectId2Res
    if isFastSelect then
        if id2Res[id] then
            return true
        end
    end
    local delta           = isSelect and 1 or -1
    local selectCount     = self.selectCount + delta
    if selectCount > self._equipReclaimMaxLimit then
        return false
    end
    id2Res[id] = isSelect
    self.selectCount      = selectCount


    ----------------------------------------
    --- 处理各个品质对应数量

    local quality         = goodsNodeData.quality
    self.qualityCounts[quality] = self.qualityCounts[quality] + delta

    ----------------------------------------
    local CNRVo = EquipUtils.GetEquipmentCNRVo(goodsNodeData)
    if CNRVo then
        -- local recycleItemNum = CNRVo.recycleItemNum[3]
        print(table.toString(CNRVo:GetRecycleItems()))
        local items = CNRVo:GetRecycleItems()[3]
        for index, value in ipairs(items) do
            local goodsId = value.goodsId
            local recycleItemNum = value.num
            local newNum = (self.goodsId2Num[goodsId] or 0) + (isSelect and recycleItemNum or -recycleItemNum)
            if newNum == 0 then
                self.goodsId2Num[goodsId] = nil
            else
                self.goodsId2Num[goodsId] = newNum
            end
        end
        -- self.goodsId2Num
        -- self.totalRecycleItemNum = self.totalRecycleItemNum + (isSelect and recycleItemNum or -recycleItemNum)
    end
    return true
end

