function CardProgressionEquipmentReclaimDialog:OnClickFontStyleButtonAction()
    if self.selectCount <= 0 then
        GameUtils.Toast(localize("无可回收的装备"))
        return
    end

    ---
    local id2SuitIdMap, coreId2SuitIdMap = equipComp:GetId2SuitIdMap()
    local suitId2WaitRemoveEquip, suitId2WaitRemoveCore = {}, {}
    local foodEquipmentList     = {}
    local foodEquipmentCoreList = {}
    for id, res in pairs(self.selectId2Res) do
        if res then
            table.insert(foodEquipmentList, id)
            local diySuitIdMap = id2SuitIdMap[tostring(id)]
            if diySuitIdMap then
                for i, diySuitId in pairs(diySuitIdMap) do
                    diySuitId = checkNumber(diySuitId)
                    suitId2WaitRemoveEquip[diySuitId] = suitId2WaitRemoveEquip[diySuitId] or {}
                    id = checkInt(id)
                    suitId2WaitRemoveEquip[diySuitId][id] = id
                end
            end
        end
    end

    local function RequestRecycle()
        local requestData = {
            playerEquipmentId     = next(foodEquipmentList) == nil     and "" or table.concat(foodEquipmentList, ','),
        }
        CardProgressionMgr:RequestOverseaEquipmentRecycle(requestData, function (responseTable)
            local code = checkNumber(responseTable.errCode)
            if code ~= 0 then return end
            ------------------------
            --- 更新全局缓存
            equipComp:RemoveInlaidDiySuitEquip(suitId2WaitRemoveEquip, suitId2WaitRemoveCore)
            equipComp:RemoveEquipsByIdList(foodEquipmentList)

            local rewards = responseTable.rewards
            self.rewards  = rewards
            GoodsUtils.DrawRewards(self.rewards)
            --------------------------

            --------------------------
            --- 清理本地缓存
            local clearDataByList = function(list)
                if list == nil then return end
                local count = #list
                for i = count, 1, -1 do
                    local data = list[i]
                    local id2Res = self.selectId2Res
                    if id2Res[data.id] then
                        table.remove(list, i)
                    end
                end
            end
            clearDataByList(self.dataList)
            clearDataByList(self.suitDataList)
            
            self.isSelectAll = false
            self:ResetSelectState()
            --------------------------
            --- 更新UI
            self:RefreshUI()
            self:GetEquipmentListEnv():RefreshEquipmentNum()
            if self.co then
                cs_coroutine.stop(self.co)
            end
            self.co = cs_coroutine.start(function ()
                UIRaycastBlocker:AddCondition('CardProgressionEquipmentReclaimDialog')
                local aniNode = nil
                local result = checkInt(responseTable.result)
                if result == 1 then
                    aniNode = self.BigSuccessNode
                elseif result == 2 then
                    aniNode = self.SuccessNode
                elseif result == 3 then
                    aniNode = self.SuccessNode2
                end
                CfUtils.SetActive(aniNode, true)
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
                CfUtils.SetActive(aniNode, false)
                UIRaycastBlocker:RemoveCondition('CardProgressionEquipmentReclaimDialog')
                UIModule.OpenDialog({id = Constants.UITypeIds.UICommonRewardPop, parameters = {rewards = rewards}})
            end)
        end)
    end

    local isRare = false
    for i, v in ipairs(self.qualityCounts) do
        if i >= Constants.QualityType.Purple and v > 0 then
            isRare = true
            break
        end
    end
    
    local isUpgrade = false
    for k, v in pairs(self.selectId2Res) do
        if v then
            local equipDojo = equipComp:GetEquipById(k)
            if checkInt(equipDojo.level) > 0 or checkInt(equipDojo.star) > 0 then
                isUpgrade = true
                break
            end
        end
    end
    if isRare or isUpgrade then
        local text = ""
        if isRare and isUpgrade then
            text = localize("已选择的装备中包含紫色及以上品质，包含<color=#E71F55>强化过的装备</color>，是否进行分解？")
        elseif isRare then
            text = localize("已选择的装备中包含紫色及以上品质，是否进行分解？")
        elseif isUpgrade then
            text = localize("已选择的装备中包含<color=#E71F55>强化过的装备</color>，是否进行分解？")
        end
        
        GameUtils.SecondConfirm(text, function()
            RequestRecycle()
        end)
        return
    end
    RequestRecycle()
end

function CardProgressionEquipmentReclaimDialog:OnClickBtnSelectAction(selectRule)
    if self.isLoadPanel then
        return
    end
    if isNull(self.SettingPanel) then
        self.isLoadPanel = true
        self.loadPanelCo = cs_coroutine.start(function ()
            self.SettingPanel = GameUtils.LoadBundleAsyncById(Constants.UIModulePrefabsIds.CultivateOverseaEquipSettingPanel, self.Container.gameObject)
            self:InitSettingPanel()
            self.isLoadPanel = false
            self.loadPanelCo = nil
        end)
    else
        KTool.SetActive(self.SettingPanel.gameObject, true)
    end

end

function CardProgressionEquipmentReclaimDialog:ChangeLockStateEventHandler(equipmentId, locked)
    if locked ~= 1 then return end

    if self.selectId2Res[checkInt(equipmentId)] then
        local list = self:GetDataList()
        for i, v in ipairs(list) do
            if v.id == checkInt(equipmentId) then
                self:HandleSelectData(v, checkInt(equipmentId), false)
                local mbEnv = self:GetEquipmentListEnv()
                if mbEnv == nil then return end
                mbEnv:UnselectData({{id = equipmentId}})
                mbEnv:RefreshCellShowStateByIndex(i, false)
                self:FreshChooseEquip()
                break
            end
        end
    end


end

function CardProgressionEquipmentReclaimDialog:LoadComparedView(curDojo, compareDojo, equipType, part)
    if self.ComparedView then
        self:FreshComparedView(curDojo, compareDojo, equipType, part)
        return
    end
    if self.ComparedViewCo then
        return
    end
    self.ComparedViewCo = cs_coroutine.start(function()
        self.ComparedView = GameUtils.LoadBundleAsyncById(Constants.UIModulePrefabsIds.CardProgressionEquipmentComparedNode, self.Container.gameObject, false, true)
        self:FreshComparedView(curDojo, compareDojo, equipType, part)
        self.ComparedViewCo = nil
    end)
end

function CardProgressionEquipmentReclaimDialog:StopComparedViewCo()
    if not isNull(self.ComparedViewCo) then
        cs_coroutine.stop(self.ComparedViewCo)
        self.ComparedViewCo = nil
    end
end

function CardProgressionEquipmentReclaimDialog:FreshComparedView(curDojo, compareDojo, equipType, part)
    ---@type UICultivateEquipComparedView
    local mbEnv = CfUtils.GetLuaScr(self.ComparedView, EquipComparedViewEnvPath)
    if not isNull(mbEnv) then
        mbEnv:RefreshEquipCultivateUI(curDojo, compareDojo, equipType, part)

        GameUtils.UpdateUIShowState(self.ComparedView.gameObject, true)
    end
end

---FreshComparedViewShowState
---刷新比较界面显示状态
---@param isShow boolean
function CardProgressionEquipmentReclaimDialog:FreshComparedViewShowState(isShow)
    if self.ComparedView == nil then return end
    GameUtils.UpdateUIShowState(self.ComparedView.gameObject, isShow)
end

