function CardProgressionEquipmentReclaimDialog:GetIcon()
    local UINavigationBarRoot = CS.UINavigationBarRoot
    local UINavigatorBarPath = "Game.Main.UINavigatorBar"
    ---@type UINavigatorBar
    local navigatorBar = CfUtils.GetLuaScr(UINavigationBarRoot.Instance.gameObject, UINavigatorBarPath)
    return navigatorBar:GetAssetNodeIconById(GoodsId)
end

function CardProgressionEquipmentReclaimDialog:InstantiateGoByLoader(loader, parent)
    local go
    if loader.IsSuccess then
        ---如果加载时parent存在，但是加载完成之后，parent已经被销毁，则当前对象也要销毁
        go = loader:Instantiate()
        if not KTool.IsNull(go) then
            KTool.SetParent(go, parent, false)
        end
    end
    loader:Release()
    return go
end

--- OnFastSelectAction
---@param luaEnv UICultivateEquipSettingPanel
function CardProgressionEquipmentReclaimDialog:OnFastSelectAction(luaEnv)
    local selectRule = luaEnv.selectRule
    if self.selectCount >= self._equipReclaimMaxLimit then
        GameUtils.Toast(localize("已达到单次回收数量上限"))
        return
    end
    self:ResetSelectState()
    if next(selectRule) == nil then
        -- 未选择不做处理
        return
    end

    local dataList         = self:GetDataList()

    local list = EquipUtils.ScreenEquipReclaimFastSelect(dataList, selectRule)
    for i = #list, 1, -1 do
        local v = list[i]
        if checkInt(v.locked) == 1 or checkInt(v.playerCardId) ~= 0 then
            table.remove(list, i)
        end
    end
    
    local selectData = {}
    for i, v in ipairs(list) do
        if not self:HandleSelectData(v, v.id, true, true) then
            break
        end
        table.insert(selectData, v)
    end

    ---@type CardProgressionReclaimEquipmentListNode
    local mbEnv = self:GetEquipmentListEnv()
    if mbEnv == nil then return end
    mbEnv:SelectData(selectData)
    
    self:RefreshUI()
end

function CardProgressionEquipmentReclaimDialog:GetEquipmentListEnv()
    return CfUtils.GetLuaScr(self.LeftPanel, "Game.CardProgression.Equip.CardProgressionReclaimEquipmentListNode")
end

function CardProgressionEquipmentReclaimDialog:GetEquipReclaimMaxLimit()
    return checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentReclaimMaxLimit))
end 
